(1, 23, 'BYOC-20260518-767467', 'Your Custom Birthday Cake Quote – Cakeouflage', 'Hi! We have reviewed your request for a Birthday cake for 25 guests. We are delighted to offer you a custom 2-tier designer cake at ?3500. This includes delivery and personalised toppings. Click the link to confirm your order!', 3500.00, 'INR', 'accepted', '2026-05-21 10:40:37', '2026-05-18 10:41:02', 163, NULL, '2026-05-18 10:40:38', '2026-05-18 10:41:02'),
(2, 24, 'BYOC-20260518-651688', 'Anniversary Cake Quote – Cakeouflage', 'Dear Parin, thank you for your anniversary cake inquiry! We have crafted a beautiful 3-tier fondant cake with floral design for 30 guests at ?4500. The price includes free delivery and custom topper. This is our ORIGINAL quote. Click the link to confirm your order!', 4500.00, 'INR', 'accepted', '2026-05-21 10:55:45', '2026-05-18 10:58:22', 164, NULL, '2026-05-18 10:55:45', '2026-05-18 10:58:22'),
(3, 24, 'BYOC-20260518-139232', 'Anniversary Cake Quote – Cakeouflage (REVISED)', 'Dear Parin, we have REVISED your quote! After a special review, we are offering you an upgraded 3-tier fondant cake with premium floral design for 30 guests at ?5000. This includes free delivery, custom topper, AND complimentary personalised message card. This is our REVISED quote with upgraded offer. Click below to confirm!', 5000.00, 'INR', 'accepted', '2026-05-21 10:57:38', '2026-05-18 11:00:39', 165, NULL, '2026-05-18 10:57:38', '2026-05-18 11:00:39'),
(4, 20, 'BYOC-20260518-993178', 'Smoke Test Quote 18 May', 'Hello, this is a smoke-test quote. Please accept to proceed with payment confirmation flow.', 4200.00, 'INR', 'cancelled', '2026-05-21 12:09:13', NULL, NULL, NULL, '2026-05-18 12:09:13', '2026-05-18 12:13:29'),
(5, 22, 'BYOC-20260518-499571', 'Flow Verify Quote 22', 'Testing BYOC flow after deployment. Please accept this quote.', 3900.00, 'INR', 'cancelled', '2026-05-21 12:09:58', NULL, 166, NULL, '2026-05-18 12:09:58', '2026-05-18 12:11:22'),
(6, 22, 'BYOC-20260518-396113', 'Flow Verify Quote 22', 'Testing BYOC flow after deployment. Please accept this quote.', 3900.00, 'INR', 'cancelled', '2026-05-21 12:11:22', NULL, 167, NULL, '2026-05-18 12:11:22', '2026-05-18 12:11:44'),
(7, 22, 'BYOC-20260518-202819', 'Flow Verify Quote 22', 'Testing BYOC flow after deployment. Please accept this quote.', 3900.00, 'INR', 'sent', '2026-05-21 12:11:44', NULL, 169, NULL, '2026-05-18 12:11:44', '2026-05-18 13:20:09'),
