(5, 'email', 'online_order_received_customer', 'Order Received - {{order_number}}', '<div style=\"background:#f5eef2;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#80001F;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"https://i.ibb.co/hRytXC3F/whitelogo.png\" alt=\"Cakeouflage Logo\" style=\"height:100px;display:block;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">Online Order Received</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">Thank you for your order with Cakeouflage. We have received it and our team is preparing your celebration.</p><div style=\"margin-top:28px;background:#fff7f9;border:1px solid #f0d7df;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Order ID:</strong> {{order_number}}</p><p><strong>Items:</strong> {{item_names}}</p><p><strong>Total:</strong> &#8377;{{grand_total}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">We will keep you posted as your order moves forward.</div></div><div style=\"background:#140b0f;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team Cakeouflage</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; www.cakeouflage.com</p></div></div></div>', 1, '2026-05-16 17:42:26', '2026-05-16 17:42:26'),
(6, 'email', 'online_order_received_admin', 'New Online Order - {{order_number}}', '<div style=\"background:#f5eef2;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#80001F;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"https://i.ibb.co/hRytXC3F/whitelogo.png\" alt=\"Cakeouflage Logo\" style=\"height:100px;display:block;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">New Online Order</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">A new online order has been received and is ready for team review.</p><div style=\"margin-top:28px;background:#fff7f9;border:1px solid #f0d7df;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Order ID:</strong> {{order_number}}</p><p><strong>Customer:</strong> {{customer_name}}</p><p><strong>Email:</strong> {{customer_email}}</p><p><strong>Phone:</strong> {{customer_phone}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">Please review fulfilment details and continue the workflow.</div></div><div style=\"background:#140b0f;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team Cakeouflage</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; www.cakeouflage.com</p></div></div></div>', 1, '2026-05-16 17:42:26', '2026-05-16 17:42:26'),
(7, 'email', 'manual_order_received_customer', 'Manual Order Received - {{order_number}}', '<div style=\"background:#f5eef2;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#80001F;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"https://i.ibb.co/hRytXC3F/whitelogo.png\" alt=\"Cakeouflage Logo\" style=\"height:100px;display:block;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">Manual Order Received</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">Your order has been recorded by the Cakeouflage team and is now in processing.</p><div style=\"margin-top:28px;background:#fff7f9;border:1px solid #f0d7df;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Order ID:</strong> {{order_number}}</p><p><strong>Items:</strong> {{item_names}}</p><p><strong>Total:</strong> &#8377;{{grand_total}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">If we need any clarification, we will contact you shortly.</div></div><div style=\"background:#140b0f;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team Cakeouflage</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; www.cakeouflage.com</p></div></div></div>', 1, '2026-05-16 17:42:26', '2026-05-16 17:42:26'),
(8, 'email', 'manual_order_received_admin', 'New Manual Order - {{order_number}}', '<div style=\"background:#f5eef2;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#80001F;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"https://i.ibb.co/hRytXC3F/whitelogo.png\" alt=\"Cakeouflage Logo\" style=\"height:100px;display:block;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">Manual Order Alert</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">A manual order has been punched in from admin and needs fulfilment review.</p><div style=\"margin-top:28px;background:#fff7f9;border:1px solid #f0d7df;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Order ID:</strong> {{order_number}}</p><p><strong>Customer:</strong> {{customer_name}}</p><p><strong>Email:</strong> {{customer_email}}</p><p><strong>Phone:</strong> {{customer_phone}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">Please verify the order details and continue the workflow.</div></div><div style=\"background:#140b0f;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team Cakeouflage</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; www.cakeouflage.com</p></div></div></div>', 1, '2026-05-16 17:42:26', '2026-05-16 17:42:26'),
(9, 'email', 'payment_confirmed_customer', 'Payment Confirmed - {{order_number}}', '<div style=\"background:#eef8f1;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#166534;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"https://i.ibb.co/hRytXC3F/whitelogo.png\" alt=\"Cakeouflage Logo\" style=\"height:100px;display:block;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">Payment Confirmed</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">We have received your payment and your order is now confirmed.</p><div style=\"margin-top:28px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Order ID:</strong> {{order_number}}</p><p><strong>Items:</strong> {{item_names}}</p><p><strong>Paid:</strong> &#8377;{{grand_total}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">Our team has started preparing your order.</div></div><div style=\"background:#052e16;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team Cakeouflage</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; www.cakeouflage.com</p></div></div></div>', 1, '2026-05-16 17:42:26', '2026-05-16 17:42:26'),
(10, 'email', 'payment_confirmed_admin', 'Payment Confirmed - {{order_number}}', '<div style=\"background:#eef8f1;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#166534;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"https://i.ibb.co/hRytXC3F/whitelogo.png\" alt=\"Cakeouflage Logo\" style=\"height:100px;display:block;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">Payment Confirmed</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">Payment has been confirmed and the order can move into production.</p><div style=\"margin-top:28px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Order ID:</strong> {{order_number}}</p><p><strong>Customer:</strong> {{customer_name}}</p><p><strong>Customer Email:</strong> {{customer_email}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">Please update the operations timeline as needed.</div></div><div style=\"background:#052e16;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team Cakeouflage</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; www.cakeouflage.com</p></div></div></div>', 1, '2026-05-16 17:42:26', '2026-05-16 17:42:26'),
