(224, 'email', 'build_your_cake_inquiry_customer_email', 'We Received Your Custom Cake Inquiry #{{inquiry_id}}', '<div style=\"background:#f5eef2;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#80001F;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"https://i.ibb.co/hRytXC3F/whitelogo.png\" alt=\"Cakeouflage Logo\" style=\"height:100px;display:block;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">Build Your Cake Inquiry</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">Thank you for sharing your custom cake brief with Cakeouflage. Our design team will review your requirements and get back with a quote soon.</p><div style=\"margin-top:28px;background:#fff7f9;border:1px solid #f0d7df;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Inquiry ID:</strong> {{inquiry_id}}</p><p><strong>Event:</strong> {{event_information}}</p><p><strong>Event Date:</strong> {{event_date}}</p><p><strong>Servings:</strong> {{number_of_servings_guests}}</p><p><strong>Budget Range:</strong> {{budget_range}}</p><p><strong>Diet Preference:</strong> {{diet_preference}}</p><p><strong>Design Notes:</strong> {{design_brief_notes}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">Need to add more details? Reply to this email and our team will assist you.</div></div><div style=\"background:#140b0f;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team Cakeouflage</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; www.cakeouflage.com</p></div></div></div>', 1, '2026-05-18 15:58:02', '2026-05-18 15:58:02'),
(225, 'email', 'build_your_cake_inquiry_admin_email', 'New BYOC Inquiry #{{inquiry_id}} - {{customer_name}}', '<div style=\"background:#f5eef2;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#80001F;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"https://i.ibb.co/hRytXC3F/whitelogo.png\" alt=\"Cakeouflage Logo\" style=\"height:100px;display:block;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">New Build Your Cake Lead</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">A new Build Your Cake inquiry has been submitted and is ready for quote action.</p><div style=\"margin-top:28px;background:#fff7f9;border:1px solid #f0d7df;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Inquiry ID:</strong> {{inquiry_id}}</p><p><strong>Name:</strong> {{customer_name}}</p><p><strong>Email:</strong> {{customer_email}}</p><p><strong>Mobile:</strong> {{phone_country_code}} {{customer_phone}}</p><p><strong>Event:</strong> {{event_information}}</p><p><strong>Event Date:</strong> {{event_date}}</p><p><strong>Servings:</strong> {{number_of_servings_guests}}</p><p><strong>Budget:</strong> {{budget_range}}</p><p><strong>Diet:</strong> {{diet_preference}}</p><p><strong>Quote Description:</strong> {{quote_description}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">Review the lead quickly and send quote from tele-calling panel for best conversion.</div></div><div style=\"background:#140b0f;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team Cakeouflage</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; www.cakeouflage.com</p></div></div></div>', 1, '2026-05-18 15:58:02', '2026-05-18 15:58:02'),
(226, 'email', 'build_your_cake_quote_email', 'Your Custom Cake Quote Is Ready - {{quote_number}}', '<div style=\"background:#eff6ff;padding:40px;font-family:Arial,sans-serif;\"><div style=\"max-width:650px;margin:auto;background:#fff;border-radius:20px;overflow:hidden;box-shadow:0 10px 35px rgba(0,0,0,0.08);\"><div style=\"background:#1d4ed8;padding:28px;color:#fff;\"><div style=\"margin-bottom:12px;\"><img src=\"https://i.ibb.co/hRytXC3F/whitelogo.png\" alt=\"Cakeouflage Logo\" style=\"height:100px;display:block;\"></div><p style=\"margin-top:10px;font-size:14px;opacity:0.9;\">Custom Cake Quote Ready</p></div><div style=\"padding:40px;\"><h2 style=\"margin-top:0;color:#1d1115;font-size:30px;\">Hi {{customer_name}}</h2><p style=\"color:#5f4c55;font-size:16px;line-height:1.8;\">Your custom cake quote has been prepared by Cakeouflage. Please review and confirm if you would like us to proceed.</p><div style=\"margin-top:28px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:16px;padding:24px;color:#3b252d;line-height:1.75;\"><p><strong>Quote Number:</strong> {{quote_number}}</p><p><strong>Inquiry ID:</strong> {{inquiry_id}}</p><p><strong>Amount:</strong> {{currency}} {{quote_amount}}</p><p><strong>Quote Summary:</strong> {{quote_description}}</p></div><div style=\"margin-top:22px;background:#fff5da;padding:18px;border-radius:12px;color:#7a5300;\">The quote link remains active for the configured validity window.</div><div style=\"margin-top:30px;\"><a href=\"{{quote_accept_link}}\" style=\"background:#1d4ed8;color:#fff;padding:14px 22px;border-radius:10px;text-decoration:none;font-weight:bold;display:inline-block;\">View &amp; Accept Quote</a></div></div><div style=\"background:#172554;padding:30px;color:#fff;\"><h3 style=\"margin-top:0;font-family:Georgia,serif;\">Team Cakeouflage</h3><p style=\"color:#d7c6cc;font-size:14px;\">Premium Designer Cakes crafted with elegance and creativity.</p><p style=\"color:#d7c6cc;font-size:14px;\">&#127760; www.cakeouflage.com</p></div></div></div>', 1, '2026-05-18 15:58:02', '2026-05-18 15:58:02');
