(1, 'Beginner Workshop Program', 'beginner-workshop-program', 'Perfect starting point for first-time bakers.', 'Hands-on sessions focused on sponge chemistry, buttercream control, piping basics and simple festive decorations.', 'Sponge foundations|Buttercream basics|Piping patterns|Simple celebration finish', '2 Days', 'offline', 4200.00, '/assets/images/courses/beginner-workshop.jpg', 'Enroll Now', '/course', 1, '2026-04-21 12:07:41', '2026-04-21 12:07:41'),
(2, 'Eggless Baking Essentials', 'eggless-baking-essentials', 'Master stable eggless textures and flavor balance.', 'Deep dive into eggless emulsions, rise support systems, shelf life control and premium decoration compatibility.', 'Eggless science|Texture balancing|Frosting stability|Storage protocols', '3 Days', 'offline', 6800.00, '/assets/images/courses/eggless-baking.jpg', 'Book Seat', '/course', 1, '2026-04-21 12:07:41', '2026-04-21 12:07:41'),
(3, 'Festive Workshop Batches', 'festive-workshop-batches', 'Seasonal showpiece cakes and dessert gifting.', 'Festival-led concepts designed for gifting demand, batch production speed, and premium packaging presentation.', 'Theme planning|Batch production|Decor workflow|Gifting assembly', '3 Days', 'hybrid', 7600.00, '/assets/images/courses/festive-workshops.jpg', 'Enroll Now', '/course', 1, '2026-04-21 12:07:41', '2026-04-21 12:07:41'),
(4, 'Professional Cake Basics', 'professional-cake-basics-course', 'Structured route for aspiring professionals.', 'A strong foundational curriculum covering costing, scaling recipes, quality controls, production planning and client briefing.', 'Recipe scaling|Costing|Production SOP|Client briefing', '4 Weeks', 'hybrid', 16500.00, '/assets/images/courses/professional-basics.jpg', 'Apply', '/course', 1, '2026-04-21 12:07:41', '2026-04-21 12:07:41');
