(2, 'Wedding Cake Showcase Evening', 'wedding-cake-showcase-evening', 'Live premium wedding cake showcase and tasting evening.', 'Presentation of signature tier systems, structure techniques, tasting panel, and consultation slots for wedding planners.', '/assets/images/events/wedding-showcase.jpg', 'Chef Ansh', '2026-05-26 17:00:00', '2026-05-26 20:00:00', 'event', 'showcase', 'scheduled', 'Cakeouflage Studio, Nashik', NULL, 60, 34, 'Register for Showcase', 1, '2026-04-21 12:07:41', '2026-04-21 12:07:41'),
(3, 'Festive Dessert Strategy Session', 'festive-dessert-strategy-session', 'Planning festive menu bundles and production calendars.', 'Operational webinar focused on festive demand forecasting, SKU rationalization, and dispatch planning for peak weeks.', '/assets/images/events/festive-strategy.jpg', 'Ops Team Cakeouflage', '2026-06-08 18:30:00', '2026-06-08 19:45:00', 'webinar', 'seasonal', 'scheduled', 'Online', 'https://meet.example.com/festive-strategy', 150, 129, 'Join Session', 1, '2026-04-21 12:07:41', '2026-04-21 12:07:41'),
(4, 'Corporate Gifting Tasting Day', 'corporate-gifting-tasting-day', 'Corporate buyers tasting and packaging preview event.', 'Invite-only tasting and gifting presentation for procurement teams evaluating annual festive and milestone gifting.', '/assets/images/events/corporate-tasting.jpg', 'B2B Team Cakeouflage', '2026-06-20 11:00:00', '2026-06-20 14:00:00', 'event', 'corporate', 'scheduled', 'Nashik Business Park Hall', NULL, 80, 52, 'Request Invitation', 1, '2026-04-21 12:07:41', '2026-04-21 12:07:41'),
(5, 'Professional Track Open House', 'professional-track-open-house', 'Open house for professional baking course admissions.', 'Meet mentors, review curriculum roadmap, and get admission guidance for the Professional Cake Basics track.', '/assets/images/events/prof-open-house.jpg', 'Academic Coordinator', '2026-06-29 16:00:00', '2026-06-29 18:00:00', 'event', 'education', 'scheduled', 'Cakeouflage Studio, Nashik', NULL, 45, 27, 'Book Open House Seat', 1, '2026-04-21 12:07:41', '2026-04-21 12:07:41'),
(6, 'Beginner QnA Live Webinar', 'beginner-qna-live-webinar', 'Live Q&A for first-time workshop participants.', 'Interactive online orientation session covering what to expect in beginner workshop batches and required tools.', '/assets/images/events/beginner-qna.jpg', 'Training Team', '2026-07-05 18:00:00', '2026-07-05 19:00:00', 'webinar', 'education', 'scheduled', 'Online', 'https://meet.example.com/beginner-qna', 100, 71, 'Join Live Q&A', 1, '2026-04-21 12:07:41', '2026-04-21 12:07:41');
