INSERT INTO `products` (`id`, `name`, `slug`, `short_description`, `long_description`, `flavour_notes`, `texture_notes`, `ingredients_summary`, `packaging_note`, `topper_note`, `sku`, `collection_category_id`, `subcategory_id`, `child_category_id`, `occasion_tag`, `dietary_tag`, `availability_status`, `lead_time_hours`, `customisation_note`, `delivery_eligible`, `pickup_eligible`, `featured_image`, `starting_price`, `base_price`, `discount_price`, `stock_quantity`, `is_featured`, `is_bestseller`, `seo_title`, `seo_description`, `rating_average`, `review_count`, `is_b2b_enabled`, `b2b_minimum_quantity`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Belgian Velvet Hazelnut Gateau 01', 'belgian-velvet-hazelnut-gateau-01', 'Premium Chocolate selection with signature finish and balanced sweetness.', 'This handcrafted creation is prepared in small batches using premium couverture, fresh dairy, and house-made components to maintain a refined finish and clean flavor profile. Each order is layered, rested, and finished by our pastry team for stable transport and elegant presentation. The profile is designed for celebrations where visual detail and reliable texture both matter. You can share preferred color palette, message plaque copy, and topper requirements at checkout. Lead time and slot selection rules are applied before final confirmation for fresh production scheduling.', 'Balanced sweetness with cocoa depth and aromatic dairy notes.', 'Soft sponge structure with smooth frosting and stable slicing texture.', 'Premium flour, cultured dairy, couverture chocolate, cane sugar, natural flavors.', 'Delivered in rigid premium box with food-safe support board and care card.', 'Custom topper text supported where design format permits.', 'CK00100001', 1, 231, 100, NULL, 'regular', 'in_stock', 24, 'Please include preferred flavor notes, color palette, writing text, and topper request while placing the order.', 1, 1, '/client/assets/images/product/cake1.jpg', 944.00, 944.00, 891.00, 60, 0, 0, 'Belgian Velvet Hazelnut Gateau | Cakeouflage', 'Order Belgian Velvet Hazelnut Gateau with delivery or pickup in Nashik. Variant pricing and custom notes supported.', 0.00, 0, 0, NULL, '2026-04-21 12:07:41', '2026-05-04 15:22:24', '2026-04-24 15:06:29'),
